alter policy kafaa_update on public.kafaa_vacancies using ((SELECT kafaa_has_grant('talent_content'::text, ARRAY['W'::text, 'A'::text]))) with check ((SELECT kafaa_has_grant('talent_content'::text, ARRAY['W'::text, 'A'::text])));
alter policy kafaa_read on public.kafaa_workforce_snapshots using (((SELECT kafaa_has_grant('workforce_analytics'::text, ARRAY['R'::text, 'W'::text, 'A'::text])) OR ((SELECT kafaa_has_grant('workforce_analytics'::text, ARRAY['Agg'::text])) AND (group_size >= 10))));
